import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { FlatCompat } from "@eslint/eslintrc";

/**
 * Linting, for the first time.
 *
 * `next lint` has always offered to set this up and never had been, so nothing
 * had ever been linted here — 25k lines written with only `tsc` watching.
 */
const compat = new FlatCompat({ baseDirectory: dirname(fileURLToPath(import.meta.url)) });

const config = [
  {
    ignores: [
      ".next/**", "node_modules/**", "public/**", "assets/**", "scripts/**", "test/**",
      // generated by Next on every build, and gitignored
      "next-env.d.ts",
    ],
  },
  ...compat.extends("next/core-web-vitals", "next/typescript"),
  {
    rules: {
      // The engine is a 4k-line class that predates this config. These are the
      // rules it trips on that are style rather than substance; leaving them
      // as errors would mean either a mechanical rewrite of working code or a
      // permanently red CI, and neither buys anything.
      "@typescript-eslint/no-unused-vars": ["error", { argsIgnorePattern: "^_", varsIgnorePattern: "^_" }],
      "react/no-unescaped-entities": "off",
      // next/image wants an image optimizer. These are two static assets — a
      // realm card and a Google avatar — and routing them through the
      // optimizer adds a per-request cost at the provider for art we already
      // compress ourselves (see scripts/optimize-textures.mjs).
      "@next/next/no-img-element": "off",
    },
  },
]

export default config;
